// Compact phone entry points for the existing event panels. The panel stays
// mounted in the same host: opening details never creates another poller or
// discards an in-progress burn, draft amount, or leaderboard.
export function mobileEventMarkup(host, { id, title, mark, action, content }) {
  // Standalone embeds keep the original full panel on every viewport.
  if (!host.hasAttribute('data-mpage')) return content;
  return `
    <button type="button" class="mobile-event-summary" data-event="${id}"
            aria-haspopup="dialog" aria-controls="${id}-mobile-details" aria-expanded="false">
      <img class="mobile-event-summary__mark" src="${mark}" alt="">
      <span class="mobile-event-summary__copy"><strong>${title}</strong><small data-event-meta>—</small></span>
      <span class="mobile-event-summary__pool"><strong data-event-pool>—</strong><small>ETH POOL</small></span>
      <span class="mobile-event-summary__action">${action}<b aria-hidden="true">›</b></span>
    </button>
    <dialog class="mobile-event-sheet" id="${id}-mobile-details" aria-label="${title}">
      <header class="mobile-event-sheet__header"><strong>${title}</strong>
        <button type="button" class="mobile-event-sheet__close" aria-label="Close ${title}" autofocus>×</button>
      </header>
      <div class="mobile-event-sheet__body">${content}</div>
    </dialog>`;
}

export function mountMobileEventSheet(host) {
  const trigger = host.querySelector('.mobile-event-summary');
  if (!trigger) return null;
  const dialog = host.querySelector('.mobile-event-sheet');
  const closeButton = host.querySelector('.mobile-event-sheet__close');
  const phone = window.matchMedia('(max-width: 768px)');
  const close = () => {
    if (phone.matches && dialog.open) {
      dialog.close();
      trigger.setAttribute('aria-expanded', 'false');
    }
  };
  const open = () => {
    if (!phone.matches || host.hidden || dialog.open) return;
    dialog.showModal();
    trigger.setAttribute('aria-expanded', 'true');
  };
  // Native close events are queued; a rapid reopen can happen before one runs.
  const onClose = () => trigger.setAttribute('aria-expanded', String(phone.matches && dialog.open));
  const onBackdrop = (event) => {
    if (event.target !== dialog) return;
    const box = dialog.getBoundingClientRect();
    if (event.clientX < box.left || event.clientX > box.right
      || event.clientY < box.top || event.clientY > box.bottom) close();
  };
  const onPage = (event) => {
    if (event.detail?.page !== 'flip') close();
  };
  const syncMode = () => {
    // Desktop uses a normal, non-modal open dialog with display:contents.
    // On phones showModal supplies focus trapping, Escape, and inertness.
    if (dialog.open) dialog.close();
    trigger.setAttribute('aria-expanded', 'false');
    if (!phone.matches) {
      dialog.setAttribute('role', 'presentation');
      dialog.show();
    } else dialog.removeAttribute('role');
  };
  trigger.addEventListener('click', open);
  closeButton.addEventListener('click', close);
  dialog.addEventListener('close', onClose);
  dialog.addEventListener('click', onBackdrop);
  phone.addEventListener('change', syncMode);
  document.addEventListener('mobile-pager:change', onPage);
  syncMode();
  return {
    open,
    update({ visible, pool, meta }) {
      if (!visible) close();
      if (pool != null) trigger.querySelector('[data-event-pool]').textContent = pool;
      if (meta != null) trigger.querySelector('[data-event-meta]').textContent = meta;
    },
    destroy() {
      if (dialog.open) dialog.close();
      trigger.removeEventListener('click', open);
      closeButton.removeEventListener('click', close);
      dialog.removeEventListener('close', onClose);
      dialog.removeEventListener('click', onBackdrop);
      phone.removeEventListener('change', syncMode);
      document.removeEventListener('mobile-pager:change', onPage);
    },
  };
}
